fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // Base case: empty interval
    if c > f {
        // All elements at indices < c are ≤ elem by invariant,
        // so the last position ≤ elem is c-1 (which may be -1).
        return c - 1;
    }

    // Compute midpoint
    let mid = c + (f - c) / 2;
    let mid_val = v[mid as usize];

    if mid_val <= elem {
        // v[mid] is ≤ elem, so answer lies in [mid+1 .. f]
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // v[mid] is > elem, so answer lies in [c .. mid-1]
        binary_search_recursive(v, elem, c, mid - 1)
    }
}

